import { clamp, damp, easeOutExpo, lerp } from "./utils";

const TRAIL = 16;

const VERT = /* glsl */ `
attribute vec2 aPos;
varying vec2 vUv;
void main() {
  vUv = aPos * 0.5 + 0.5;
  gl_Position = vec4(aPos, 0.0, 1.0);
}`;

const FRAG = /* glsl */ `
precision highp float;
#define TRAIL ${TRAIL}
uniform sampler2D uTex;
uniform vec2 uRes;
uniform vec2 uImg;
uniform vec2 uFocus;
uniform vec2 uPar;
uniform float uTime;
uniform float uReveal;
uniform float uDpr;
uniform vec3 uTrail[TRAIL];
varying vec2 vUv;

