  float n2 = noise(css * 0.035 + vec2(0.0, -uTime * 0.6));

  // lantern: a comet of soft discs with a ragged, smouldering rim
  float m = 0.0;
  for (int i = 0; i < TRAIL; i++) {
    vec3 t = uTrail[i];
