  plate.addEventListener("pointermove", (e) => {
    const r = plate.getBoundingClientRect();
    lens.tx = e.clientX - r.left;
    lens.ty = e.clientY - r.top;
    if (lens.o < 0.01) {
      lens.x = lens.tx;
      lens.y = lens.ty;
    }
  });

