          s.style.setProperty("--d", String(i++));
          s.style.setProperty("--r", (0.35 + Math.random() * 0.9).toFixed(2));
          s.style.setProperty("--rot", ((Math.random() - 0.5) * 50).toFixed(1));
          frag.append(s);
        }
        child.replaceWith(frag);
      } else walk(child);
    });
  };
