    if (x <= -half) x += half;
    if (x > 0) x -= half;
    track.style.transform = `translate3d(${x.toFixed(2)}px,0,0) skewX(${(-v * 0.25).toFixed(2)}deg)`;
  });
});

/* ---------- manifesto ---------- */

{
  const text = $("[data-split]");
  const words = splitWords(text, (word) => {
    const s = document.createElement("span");
